import { Cause, Data, Duration, Effect } from "effect";

import type { HevyOperationSafety } from "./execution.js";

export interface BackoffFailureOptions {
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}

/** Internal typed failure used while adapting a retry wait. */
export class BackoffFailure extends Data.TaggedError("BackoffFailure")<{
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}> {}

function interruptionEffect(
	signal: AbortSignal,
): Effect.Effect<never, unknown> {
	return Effect.callback<never, unknown>((resume, interruptionSignal) => {
		const cleanup = () => {
			signal.removeEventListener("abort", fail);
			interruptionSignal.removeEventListener("abort", cleanup);
		};
		const fail = () =>
			resume(
				Effect.fail(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				),
			);
		if (signal.aborted) {
			fail();
			return;
		}
		signal.addEventListener("abort", fail, { once: true });
		interruptionSignal.addEventListener("abort", cleanup, { once: true });
		return Effect.sync(cleanup);
	}).pipe(Effect.interruptible);
}

/**
 * Wait using the Effect Clock while still observing the operation signal.
 * This is deliberately separate from the Promise adapter so TestClock can
 * control the actual production retry wait.
 */
export function effectClockSleep(
	delayMs: number,
	signal: AbortSignal,
): Effect.Effect<void, unknown> {
	if (signal.aborted) {
		return Effect.fail(
			signal.reason ?? new DOMException("Operation canceled", "AbortError"),
		);
	}
	const sleep = Effect.sleep(Duration.millis(Math.max(0, delayMs)));
	return Effect.raceFirst(sleep, interruptionEffect(signal)).pipe(
		Effect.asVoid,
	);
}

/**
 * Adapt the established Promise sleep hook to an interruptible Effect.
 * Synchronous throws are captured by tryPromise just like rejections.
 */
export function customPromiseSleep(
	delayMs: number,
	signal: AbortSignal,
	sleep: (milliseconds: number, signal?: AbortSignal) => Promise<void>,
	deadline?: number,
): Effect.Effect<void, unknown> {
	return Effect.tryPromise({
		try: (interruptionSignal) => {
			if (signal.aborted) {
				return Promise.reject(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				);
			}
			return new Promise<void>((resolve, reject) => {
				let settled = false;
				const cleanup = () => {
					signal.removeEventListener("abort", onOperationAbort);
					interruptionSignal.removeEventListener("abort", onInterruptionAbort);
				};
				const settleReject = (cause: unknown) => {
					if (settled) return;
					settled = true;
					cleanup();
					reject(cause);
				};
				const onOperationAbort = () =>
					settleReject(
						signal.reason ??
							new DOMException("Operation canceled", "AbortError"),
					);
				const onInterruptionAbort = () =>
					settleReject(new DOMException("Effect interrupted", "AbortError"));
				signal.addEventListener("abort", onOperationAbort, { once: true });
				interruptionSignal.addEventListener("abort", onInterruptionAbort, {
					once: true,
				});
				if (signal.aborted) {
					onOperationAbort();
					return;
				}
				try {
					Promise.resolve(sleep(delayMs, signal)).then(() => {
						if (settled) return;
						if (deadline !== undefined && Date.now() >= deadline) {
							settleReject(
								new Cause.TimeoutError("Retry backoff deadline exceeded"),
							);
							return;
						}
						settled = true;
						cleanup();
						resolve();
					}, settleReject);
				} catch (cause) {
					settleReject(cause);
				}
			});
		},
		catch: (cause) => cause,
	});
}

export function retryBackoff(
	options: BackoffFailureOptions & {
		readonly delayMs: number;
		readonly sleep?: (
			milliseconds: number,
			signal?: AbortSignal,
		) => Promise<void>;
		readonly signal: AbortSignal;
	},
): Effect.Effect<void, BackoffFailure> {
	const wait = options.sleep
		? customPromiseSleep(
				options.delayMs,
				options.signal,
				options.sleep,
				options.deadline,
			)
		: effectClockSleep(options.delayMs, options.signal);
	return wait.pipe(
		Effect.mapError(
			(cause) =>
				new BackoffFailure({
					cause,
					method: options.method,
					endpoint: options.endpoint,
					phase: "backoff",
					operationSafety: options.operationSafety,
					deadline: options.deadline,
				}),
		),
	);
}

import { Duration, Effect, Schedule } from "effect";

import type { HevyHttpError } from "./hevy-http-error.js";
import {
	DEFAULT_RETRY_POLICY,
	getRetryDelayMs,
	type RetryPolicy,
} from "./retry-policy.js";

export type RetryScheduleInput = Pick<HevyHttpError, "status" | "headers">;

export interface RetryScheduleOptions<ScheduleError = never> {
	/**
	 * Decides whether the schedule may continue for the current failure.
	 * Effect 4 exposes this as `Schedule.while` over schedule metadata,
	 * including the input failure.
	 */
	readonly whileInput?: (
		input: RetryScheduleInput,
		attempt: number,
	) => boolean | Effect.Effect<boolean, never>;
	/**
	 * Optional adapter for callers that need to observe or bound a calculated
	 * delay. The returned duration is the wait that Schedule will own.
	 */
	readonly delay?: (
		input: RetryScheduleInput,
		attempt: number,
		delayMs: number,
	) => Effect.Effect<Duration.Input, ScheduleError>;
}

/**
 * Builds the Effect schedule used by retrying client programs.
 *
 * The schedule owns retry timing, recurrence, and the input predicate. The
 * client supplies the safety predicate and optional delay adapter for
 * observation or deadline bounding.
 */
export function createRetrySchedule<ScheduleError = never>(
	maxRetries: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
	options: RetryScheduleOptions<ScheduleError> = {},
): Schedule.Schedule<number, RetryScheduleInput, ScheduleError> {
	return Schedule.recurs(Math.max(0, maxRetries)).pipe(
		Schedule.while(
			(metadata: Schedule.Metadata<number, RetryScheduleInput>) =>
				options.whileInput?.(metadata.input, metadata.attempt) ?? true,
		),
		Schedule.addDelay((metadata) =>
			Effect.gen(function* () {
				const delayMs = getRetryDelayMs(
					metadata.input,
					metadata.attempt,
					policy,
					randomInt,
				);
				return yield* options.delay
					? options.delay(metadata.input, metadata.attempt, delayMs)
					: Effect.succeed(Duration.millis(delayMs));
			}),
		),
	);
}

import { Data, Effect } from "effect";

import type {
	HevyCommitState,
	HevyOperationSafety,
	HevyRequestPhase,
} from "./execution.js";

export interface AttemptFailureOptions {
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: HevyRequestPhase;
	readonly operationSafety: HevyOperationSafety;
	readonly commitState: HevyCommitState;
	readonly responseConfirmed: boolean;
	readonly deadline?: number;
	readonly retryCount: number;
}

/** Typed internal channel for a dispatch or response-consumption failure. */
export class AttemptFailure extends Data.TaggedError("AttemptFailure")<{
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: HevyRequestPhase;
	readonly operationSafety: HevyOperationSafety;
	readonly commitState: HevyCommitState;
	readonly responseConfirmed: boolean;
	readonly deadline?: number;
	readonly retryCount: number;
}> {}

/**
 * Adapt one asynchronous attempt to Effect while retaining the metadata
 * needed by the transition policy if the adapter itself throws.
 */
export function attemptEffect<A>(
	options: AttemptFailureOptions & {
		readonly run: (signal: AbortSignal) => Promise<A>;
	},
): Effect.Effect<A, AttemptFailure> {
	return Effect.tryPromise({
		try: options.run,
		catch: (cause) =>
			new AttemptFailure({
				cause,
				method: options.method,
				endpoint: options.endpoint,
				phase: options.phase,
				operationSafety: options.operationSafety,
				commitState: options.commitState,
				responseConfirmed: options.responseConfirmed,
				deadline: options.deadline,
				retryCount: options.retryCount,
			}),
	});
}

/** Make observer and resource finalizers idempotent at their Effect seam. */
export function finalizeOnce(finalizer: () => void): () => void {
	let finalized = false;
	return () => {
		if (finalized) return;
		finalized = true;
		try {
			finalizer();
		} catch {
			// Resource finalization is best-effort and cannot replace settlement.
		}
	};
}

import { Effect } from "effect";

/**
 * Bridge an external AbortSignal into fiber interruption.
 *
 * The signal's reason is preserved by the caller that collapses the
 * interruption. This helper owns only the interruption and listener lifecycle
 * so adapters can share the same race and cleanup semantics.
 */
export function interruptOnAbortSignal(
	signal: AbortSignal,
): Effect.Effect<never> {
	return Effect.callback<never, never>((resume, interruptionSignal) => {
		const cleanup = () => {
			signal.removeEventListener("abort", onAbort);
			interruptionSignal.removeEventListener("abort", cleanup);
		};
		const onAbort = () => resume(Effect.interrupt);
		if (signal.aborted) onAbort();
		else signal.addEventListener("abort", onAbort, { once: true });
		interruptionSignal.addEventListener("abort", cleanup, { once: true });
		return Effect.sync(cleanup);
	}).pipe(Effect.interruptible);
}

import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { Cache, Effect, Exit, Layer, Schema, Scope } from "effect";
import { createOperations } from "@hevy-mcp/operations";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import {
	createExerciseTemplateCatalog,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
import { mergeAbortSignals } from "./execution.js";
import {
	createCoreServiceLayer,
	createToolObserverLayer,
	type CoreServiceLayer,
} from "./effect-layer.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
	/**
	 * Optional additional server-owned services. The layer is built in the
	 * construction Scope and can replace the default service implementations.
	 */
	readonly serviceLayer?: CoreServiceLayer;
}

/** A safe construction failure raised before an MCP server is exposed. */
export class HevyMcpServerConstructionError extends Schema.TaggedError<HevyMcpServerConstructionError>()(
	"HevyMcpServerConstructionError",
	{ message: Schema.String },
) {}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

/**
 * Construct a server in a caller-owned Scope.
 *
 * Keeping this as an Effect makes the lifetime of the catalog explicit. The
 * Promise façade below opens a Scope and attaches its release to `close()`.
 */
export const createHevyMcpServerEffect = Effect.fn("core.createHevyMcpServer")(
	function* (
		options: CreateHevyMcpServerOptions,
	): Effect.fn.Return<McpServer, HevyMcpServerConstructionError, Scope.Scope> {
		const baseServer = new McpServer(
			{ name: SERVER_NAME, version: SERVER_VERSION },
			{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
		);
		const server = options.decorateServer?.(baseServer) ?? baseServer;
		const mcpLogger = createMcpClientLogger(server);
		const client = options.createClient({ onLog: (event) => mcpLogger(event) });
		const operations = createOperations(client);
		const templateListAll = operations.templates?.listAll;
		if (!templateListAll) {
			return yield* new HevyMcpServerConstructionError({
				message: "Exercise template list operation is unavailable.",
			});
		}
		const shutdown = new AbortController();
		const lifecycleSignal = options.lifecycleSignal
			? mergeAbortSignals(options.lifecycleSignal, shutdown.signal)
			: shutdown.signal;
		const cache = yield* Cache.make<
			string,
			ExerciseTemplate[],
			Effect.Error<ReturnType<TemplatesListAllOperation["effect"]>>
		>({
			capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
			timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
			lookup: (_key: string) => templateListAll.effect(),
		});
		const catalog = createExerciseTemplateCatalog(
			operations,
			cache,
			options.cacheObserver,
		);
		const defaultServiceLayer = createCoreServiceLayer({
			client,
			catalog,
			execution: {},
			operations,
		});
		let serviceLayer: CoreServiceLayer = defaultServiceLayer;
		if (options.observer) {
			serviceLayer = Layer.merge(
				serviceLayer,
				createToolObserverLayer(options.observer),
			) as CoreServiceLayer;
		}
		if (options.serviceLayer) {
			serviceLayer = Layer.merge(
				serviceLayer,
				options.serviceLayer,
			) as CoreServiceLayer;
		}
		const services = yield* Layer.build(serviceLayer);
		yield* Effect.addFinalizer(() => {
			shutdown.abort(new DOMException("Server closed", "AbortError"));
			catalog.close?.();
			return Cache.invalidateAll(cache);
		});
		const runtime = createToolRuntime({
			client,
			operations,
			catalog,
			logger: mcpLogger,
			observer: options.observer,
			executionTimeoutMs: options.executionTimeoutMs,
			executionDeadline: options.executionDeadline,
			lifecycleSignal,
			services,
		});
		const counting = createCountingServer(server);
		registerHevyTools(counting.server, runtime);
		options.onToolsRegistered?.(counting.getCount());
		registerWorkoutPrompts(server, options.observer, mcpLogger);
		registerHevyResources(server, runtime);
		return server;
	},
);

export async function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): Promise<McpServer> {
	const scope = Effect.runSync(Scope.make());
	let server: McpServer;
	try {
		server = Effect.runSync(
			Scope.provide(scope)(createHevyMcpServerEffect(options)),
		);
	} catch (error) {
		// Construction can acquire several scoped services before a later
		// registration/decorator fails. Close the caller-owned Scope before
		// exposing the failure so every partial acquisition is released once.
		await Effect.runPromiseExit(Scope.close(scope, Exit.fail(error)));
		throw error;
	}
	const close = server.close.bind(server);
	let closePromise: Promise<void> | undefined;
	server.close = async () => {
		closePromise ??= (async () => {
			try {
				await close();
			} finally {
				await Effect.runPromise(Scope.close(scope, Exit.succeed(undefined)));
			}
		})();
		await closePromise;
	};
	return server;
}

import type { McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { Effect } from "effect";
import { z } from "zod";
import { ClientNotInitializedError } from "../effect-errors.js";
import { HevyOperationsService } from "../effect-services.js";
import { respond, type ResponseContract } from "../utils/response-contracts.js";
import { compactJsonSchema } from "../utils/compact-json-schema.js";
import type { InferToolParams } from "../utils/tool-helpers.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import type { ToolRuntime } from "./tool-runtime.js";
import type { ToolExecutionContext } from "../execution.js";
import {
	ToolInputValidationError,
	type CoreToolError,
} from "../effect-errors.js";
import { normalizeCoreCause } from "./operation-helpers.js";

type ToolDefinitionBase<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: TSchema;
	readonly annotations: ToolAnnotations;
	readonly responseContract: ResponseContract<TResult>;
	execute(
		runtime: ToolRuntime,
		args: InferToolParams<TSchema>,
	): Effect.Effect<TResult, CoreToolError, never>;
};

type RegisteredToolConfig = {
	description: string;
	inputSchema: ReturnType<typeof compactJsonSchema>;
	annotations: ToolAnnotations;
	outputSchema?: ReturnType<typeof compactJsonSchema>;
};

export type ToolRegistrar = Pick<McpServer, "registerTool">;

export type ToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = ToolDefinitionBase<TSchema, TResult> &
	(
		| {
				readonly kind: "read";
				readonly outputSchema: z.ZodRawShape;
		  }
		| {
				readonly kind: "write";
				readonly outputSchema?: z.ZodRawShape;
		  }
	);

type ToolDefinitionMetadata = {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: Record<string, z.ZodTypeAny>;
	readonly annotations: ToolAnnotations;
	readonly outputSchema?: z.ZodRawShape;
};
type RegistrationArgs = z.output<z.ZodObject<Record<string, z.ZodTypeAny>>>;

type UntypedToolDefinition = ToolDefinitionMetadata &
	Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
		readonly kind: "read" | "write";
		readonly responseContract: ResponseContract<unknown>;
		execute(
			runtime: ToolRuntime,
			args: RegistrationArgs,
		): Effect.Effect<unknown, CoreToolError, never>;
	};

/**
 * One-time-per-isolate registration metadata for each tool definition.
 *
 * Building a tool's compact JSON Schema (and the SDK's eager wire conversion
 * of the `compactJsonSchema`-wrapped schema on registration) is the dominant
 * CPU cost when constructing an MCP server. Tool definitions are module-level
 * constants, so this metadata can be computed once and shared by every server
 * a single isolate builds. The SDK's `registerTool` reads the schema strictly
 * through the Standard Schema interface and never mutates it, so sharing the
 * memoized config across concurrent servers is safe.
 *
 * Keep the memo lazy: CLI and test processes that never build a Hevy server
 * pay nothing. Isolate-based edge runtimes that want the one-time conversion
 * moved into module-scope (outside request CPU) call `preloadHevyToolSchemas`.
 */
const registeredToolConfigCache = new WeakMap<
	ToolDefinitionMetadata,
	RegisteredToolConfig
>();

export function getRegisteredToolConfig(
	definition: ToolDefinitionMetadata,
): RegisteredToolConfig {
	const cached = registeredToolConfigCache.get(definition);
	if (cached) return cached;
	const config: RegisteredToolConfig = {
		description: definition.description,
		inputSchema: compactJsonSchema(z.strictObject(definition.inputSchema)),
		annotations: definition.annotations,
	};
	if (definition.outputSchema) {
		config.outputSchema = compactJsonSchema(z.object(definition.outputSchema));
	}
	registeredToolConfigCache.set(definition, config);
	return config;
}

export function registerToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
>(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: ToolDefinition<TSchema, TResult>,
): void;
export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: UntypedToolDefinition,
): void;
export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: UntypedToolDefinition,
): void {
	const directHandler = (
		args: RegistrationArgs,
		requestContext?: ToolExecutionContext,
	) =>
		Effect.suspend(() => {
			const scopedRuntime = requestContext
				? runtime.forExecution(requestContext)
				: runtime;
			// Fail inside the Effect so the tagged initialization error reaches
			// the collapse boundary instead of becoming an untyped defect.
			if (!scopedRuntime.client) {
				try {
					scopedRuntime.service(HevyOperationsService);
				} catch {
					return Effect.fail(new ClientNotInitializedError());
				}
			}
			return Effect.catchCause(
				Effect.suspend(() =>
					definition
						.execute(scopedRuntime, args)
						.pipe(
							Effect.map((data) => respond(definition.responseContract, data)),
						),
				),
				(cause) => Effect.failCause(normalizeCoreCause(cause)),
			);
		});
	const handler = runtime.createHandler(directHandler, definition.name, {
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
	});
	const invalidInputHandler = runtime.createHandler(
		(args: { path: string }) =>
			Effect.fail(new ToolInputValidationError({ path: args.path })),
		definition.name,
		{
			feature: definition.feature,
			kind: definition.kind,
			operation: definition.operation,
		},
	);

	const config = getRegisteredToolConfig(definition);
	server.registerTool(definition.name, config, (args, context) => {
		let parsed: RegistrationArgs;
		try {
			parsed = z.strictObject(definition.inputSchema).parse(args ?? {});
		} catch (error) {
			const path =
				error instanceof z.ZodError
					? error.issues[0]?.path
							?.map((segment) => String(segment))
							.join(".") || "arguments"
					: "arguments";
			if (context) {
				return invalidInputHandler(
					{ path },
					{
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					},
				);
			}
			throw new ToolInputValidationError({ path });
		}
		return handler(
			parsed,
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		);
	});
}

import { Cause, Context, Effect } from "effect";
import {
	ApiError,
	ClientNotInitializedError,
	EmptyMeasurementUpdateError,
	NetworkError,
	NotFoundError,
	OperationUnavailableError,
	PaginationMismatchError,
	RateLimitError,
	ToolInputValidationError,
	TrainingSummaryDataError,
	TrainingSummaryValidationError,
	ValidationError,
	WorkoutPayloadError,
	WorkoutPrivacyError,
	type CoreToolError,
} from "../effect-errors.js";
import type { RuntimeValue } from "../utils/type-predicates.js";

type EffectOperation<TArgs extends readonly unknown[], TResult> = {
	readonly effect: (...args: TArgs) => Effect.Effect<TResult, unknown, never>;
};

export function normalizeCoreEffect<A, E>(
	effect: Effect.Effect<A, E, never>,
): Effect.Effect<A, CoreToolError, never> {
	return Effect.catchCause(effect, (cause) =>
		Effect.failCause(normalizeCoreCause(cause)),
	);
}

export function requireOperation<T>(
	operation: T | undefined,
	id: string,
): Effect.Effect<T, OperationUnavailableError, never> {
	return operation === undefined
		? Effect.fail(new OperationUnavailableError({ operation: id }))
		: Effect.succeed(operation);
}

function isCoreToolError(error: RuntimeValue): error is CoreToolError {
	return (
		error instanceof ToolInputValidationError ||
		error instanceof ClientNotInitializedError ||
		error instanceof OperationUnavailableError ||
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError ||
		error instanceof EmptyMeasurementUpdateError ||
		error instanceof PaginationMismatchError ||
		error instanceof TrainingSummaryDataError ||
		error instanceof TrainingSummaryValidationError ||
		error instanceof WorkoutPayloadError ||
		error instanceof WorkoutPrivacyError
	);
}

/**
 * Keep supported upstream tags typed at the core boundary. An operation is
 * external to core and its failure channel is intentionally unknown, so
 * hostile values become defects rather than widening every tool handler.
 */
export function normalizeCoreCause(
	cause: Cause.Cause<unknown>,
): Cause.Cause<CoreToolError> {
	return Cause.fromReasons(
		cause.reasons.map((reason) => {
			if (!Cause.isFailReason(reason)) return reason;
			const normalized = isCoreToolError(reason.error)
				? Cause.makeFailReason(reason.error)
				: Cause.makeDieReason(reason.error);
			return normalized.annotate(Context.makeUnsafe(reason.annotations));
		}),
	);
}

export function operationEffect<TArgs extends readonly unknown[], TResult>(
	operation: Effect.Effect<
		EffectOperation<TArgs, TResult>,
		OperationUnavailableError,
		never
	>,
	...args: TArgs
): Effect.Effect<TResult, CoreToolError, never> {
	// The operation package owns the external Effect seam. Normalize it once,
	// before the value reaches ToolEffectHandler or a tool definition.
	return Effect.flatMap(operation, (resolved) =>
		normalizeCoreEffect(Effect.suspend(() => resolved.effect(...args))),
	);
}

import { Cache, Clock, Deferred, Effect, Fiber, Option } from "effect";
import type { HevyRequestOptions } from "@hevy-mcp/hevy-client";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import type {
	CacheObservationMetadata,
	CacheObservationScope,
	CacheObservationState,
	CacheObserver,
} from "./cache.js";
import { bucketCount } from "./result-telemetry.js";

export const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
export const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
export const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;
const EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE = 100;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

type TemplateListAllError = Effect.Error<
	ReturnType<TemplatesListAllOperation["effect"]>
>;
export type ExerciseTemplateCatalogCache = Cache.Cache<
	string,
	ExerciseTemplate[],
	TemplateListAllError
>;
export interface ExerciseTemplateCatalog {
	effect(
		options?: ExerciseTemplateCatalogOptions,
	): Effect.Effect<ExerciseTemplate[], TemplateListAllError>;
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
	close?(): void;
}

type CatalogOperations = {
	readonly templates?: {
		readonly listAll?: Pick<TemplatesListAllOperation, "effect">;
	};
};

function startObservation(
	observer: CacheObserver | undefined,
	state: CacheObservationState,
) {
	try {
		return observer?.start({ state });
	} catch {
		return undefined;
	}
}
function finishObservation(
	scope: CacheObservationScope | void,
	metadata?: CacheObservationMetadata,
): void {
	try {
		scope?.finish(metadata);
	} catch {
		// Observability is not allowed to affect catalog behavior.
	}
}
function notifyRefreshed(
	options: ExerciseTemplateCatalogOptions,
	catalog: ExerciseTemplate[],
	reason: ExerciseTemplateCatalogRefreshReason,
): void {
	try {
		const callback = options.onRefreshed;
		if (!callback) return;
		// Refresh notifications are telemetry. Defer invocation so both
		// synchronous throws and rejected promises are contained here.
		void Promise.resolve()
			.then(() => callback(catalog, reason))
			.catch(() => undefined);
	} catch {
		// Callbacks are best effort.
	}
}
function catalogPageCount(catalog: readonly ExerciseTemplate[]): number {
	const pages = (
		catalog as ExerciseTemplate[] & { readonly pageCount?: number }
	).pageCount;
	return (
		pages ??
		Math.max(1, Math.ceil(catalog.length / EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE))
	);
}

export function createExerciseTemplateCatalog(
	operations: CatalogOperations,
	cache: ExerciseTemplateCatalogCache,
	cacheObserver?: CacheObserver,
): ExerciseTemplateCatalog {
	const listAll = operations.templates?.listAll;
	if (!listAll)
		throw new Error("Exercise template list operation is unavailable.");

	let hasLoadedValue = false;
	let generation = 0;
	let inFlight:
		| {
				deferred: Deferred.Deferred<ExerciseTemplate[], TemplateListAllError>;
				fiber: Fiber.Fiber<boolean, never>;
				waiters: number;
				refresh: boolean;
		  }
		| undefined;

	const getState = Effect.fn("core.exerciseTemplateCatalog.cacheState")(
		function* () {
			const success = yield* Cache.getSuccess(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			if (Option.isSome(success)) return "hit" as const;
			const present = yield* Cache.has(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			return present
				? ("inflight_wait" as const)
				: hasLoadedValue
					? ("expired" as const)
					: ("miss" as const);
		},
	);

	const awaitAbort = (signal: AbortSignal) =>
		Effect.callback<never, TemplateListAllError>((resume) => {
			const abort = () =>
				resume(
					Effect.fail(
						signal.reason ??
							new DOMException("Operation canceled", "AbortError"),
					) as Effect.Effect<never, TemplateListAllError>,
				);
			if (signal.aborted) abort();
			else signal.addEventListener("abort", abort, { once: true });
			return Effect.sync(() => signal.removeEventListener("abort", abort));
		});

	const effect = Effect.fn("core.exerciseTemplateCatalog.get")(function* (
		options: ExerciseTemplateCatalogOptions = {},
	): Effect.fn.Return<ExerciseTemplate[], TemplateListAllError> {
		const refresh = options.refresh === true;
		const state = refresh ? "refresh" : yield* getState();
		const observationScope = startObservation(cacheObserver, state);
		const reason: ExerciseTemplateCatalogRefreshReason =
			state === "refresh"
				? "explicit-refresh"
				: state === "expired"
					? "ttl-expired"
					: "initial-load";
		let metadata: CacheObservationMetadata | undefined;
		const currentGeneration = ++generation;
		const load = Effect.gen(function* () {
			const catalog = yield* refresh
				? listAll.effect()
				: Cache.get(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY);
			if (refresh)
				yield* Cache.set(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY, catalog);
			hasLoadedValue = true;
			return catalog;
		});
		let shared =
			inFlight && (!refresh || inFlight.refresh) ? inFlight : undefined;
		if (!shared) {
			const deferred = yield* Deferred.make<
				ExerciseTemplate[],
				TemplateListAllError
			>();
			const fiber = yield* Effect.forkDetach(
				Effect.ensuring(
					Effect.flatMap(Effect.exit(load), (exit) =>
						Deferred.done(deferred, exit),
					),
					Effect.sync(() => {
						if (inFlight?.deferred === deferred) inFlight = undefined;
					}),
				),
			);
			shared = { deferred, fiber, waiters: 0, refresh };
			inFlight = shared;
		}
		const loaded = Effect.gen(function* () {
			shared.waiters += 1;
			return yield* Effect.ensuring(
				Deferred.await(shared.deferred).pipe(
					Effect.raceFirst(
						options.execution?.signal
							? awaitAbort(options.execution.signal)
							: Effect.never,
					),
				),
				Effect.sync(() => {
					shared.waiters -= 1;
					if (shared.waiters === 0 && inFlight === shared) {
						inFlight = undefined;
						void Effect.runPromise(Fiber.interrupt(shared.fiber));
					}
				}),
			);
		});
		const controlled = options.execution
			? checkExecution(options.execution).pipe(Effect.flatMap(() => loaded))
			: loaded;
		return yield* Effect.ensuring(
			controlled.pipe(
				Effect.tap((catalog) =>
					Effect.sync(() => {
						if (currentGeneration === generation && state !== "hit") {
							metadata = {
								refreshReason: reason,
								pageCountBucket: bucketCount(catalogPageCount(catalog)),
								itemCountBucket: bucketCount(catalog.length),
							};
							if (state !== "inflight_wait")
								notifyRefreshed(options, catalog, reason);
						}
					}),
				),
				Effect.catch((error) =>
					Effect.flatMap(
						Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY),
						() => Effect.fail(error),
					),
				),
			),
			Effect.sync(() => finishObservation(observationScope, metadata)),
		);
	});

	return {
		effect,
		get: (options) => Effect.runPromise(effect(options)),
		reset() {
			hasLoadedValue = false;
			generation += 1;
			if (inFlight) void Effect.runPromise(Fiber.interrupt(inFlight.fiber));
			inFlight = undefined;
			Effect.runSync(
				Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY),
			);
		},
		close() {
			if (inFlight) void Effect.runPromise(Fiber.interrupt(inFlight.fiber));
			inFlight = undefined;
		},
	};
}

function checkExecution(execution: HevyRequestOptions) {
	return Effect.gen(function* () {
		if (execution.signal?.aborted) {
			return yield* Effect.fail(
				execution.signal.reason ??
					new DOMException("Operation canceled", "AbortError"),
			);
		}
		const now = yield* Clock.currentTimeMillis;
		if (execution.deadline !== undefined && now >= execution.deadline) {
			return yield* Effect.fail(
				new DOMException("Operation deadline exceeded", "TimeoutError"),
			);
		}
	});
}

import { Effect, Logger, LogLevel } from "effect";
import type {
	McpClientLogMessage,
	McpClientLogger,
} from "./mcp-client-logger-types.js";
import type { SafeErrorDiagnostic } from "./error-policy.js";

const levelForMcp = (
	level: LogLevel.LogLevel,
): McpClientLogMessage["level"] => {
	switch (level) {
		case "Debug":
			return "debug";
		case "Warn":
			return "warning";
		case "Error":
		case "Fatal":
			return "error";
		default:
			return "info";
	}
};

/**
 * Emit a bounded diagnostic through Effect's logger. The default Effect
 * logger writes to stderr; the optional MCP logger is an additional sink.
 * Logger failures are deliberately swallowed at this telemetry boundary.
 */
export function logCoreError(
	message: string,
	data?: SafeErrorDiagnostic,
	mcpLogger?: McpClientLogger,
): void {
	try {
		const sink = mcpLogger
			? Logger.make(({ message: loggedMessage, logLevel }) => {
					mcpLogger({
						level: levelForMcp(logLevel),
						logger: "hevy-core",
						data: {
							message: String(loggedMessage),
							...(data ?? {}),
						},
					});
				})
			: undefined;
		const stderr = Logger.make(({ message: loggedMessage }) => {
			if (data === undefined) {
				console.error(String(loggedMessage));
			} else {
				console.error(String(loggedMessage), data);
			}
		});
		const program = Effect.logError(message).pipe(
			Effect.provide(Logger.layer(sink ? [stderr, sink] : [stderr])),
		);
		Effect.runSync(program);
	} catch {
		// Observability is never allowed to change the business outcome.
	}
}

import { SpanStatusCode, type Span } from "@opentelemetry/api";
import { Data, Effect, Exit, Layer, Scope } from "effect";
import {
	serviceName,
	serviceVersion,
	tracer,
	captureFailure,
	flushTelemetry,
	installProcessExceptionTracking,
	telemetryLayer,
} from "./telemetry.js";
import { serverStartups } from "./metrics.js";
import { installGracefulShutdown } from "./graceful-shutdown.js";
import { scheduleUpdateCheck } from "./version-check.js";
import { MissingHevyApiKeyError } from "./config.js";
import type { FailureContext } from "./failure-reporter.js";
import {
	INVALID_API_KEY_MESSAGE,
	InvalidHevyApiKeyError,
} from "./startup-errors.js";
export { INVALID_API_KEY_MESSAGE } from "./startup-errors.js";

type LifecycleFailurePhase =
	| "config"
	| "api_key_validation"
	| "build"
	| "connect"
	| "run";

type LifecycleTerminationReason =
	| "connect_failure"
	| "runtime_failure"
	| "startup_failure";

class LifecycleFailure extends Data.TaggedError("LifecycleFailure")<{
	readonly cause: Error | string;
	readonly phase: LifecycleFailurePhase;
}> {}

const LIFECYCLE_FAILURE_TAXONOMY = {
	config: {
		errorType: "MCP_SERVER_CONFIG_ERROR",
		errorCategory: "McpServerConfigFailure",
	},
	api_key_validation: {
		errorType: "MCP_API_KEY_VALIDATION_ERROR",
		errorCategory: "McpApiKeyValidationFailure",
	},
	build: {
		errorType: "MCP_SERVER_BUILD_ERROR",
		errorCategory: "McpServerBuildFailure",
	},
	connect: {
		errorType: "MCP_TRANSPORT_CONNECT_ERROR",
		errorCategory: "McpTransportConnectFailure",
	},
	run: {
		errorType: "MCP_SERVER_RUN_ERROR",
		errorCategory: "McpServerRunFailure",
	},
} satisfies Record<
	LifecycleFailurePhase,
	{ errorType: string; errorCategory: string }
>;

function isExpectedLifecycleFailure(error: Error | string): boolean {
	return (
		error instanceof MissingHevyApiKeyError ||
		error instanceof InvalidHevyApiKeyError ||
		(error instanceof Error && error.message === INVALID_API_KEY_MESSAGE)
	);
}

function createLifecycleFailureAttributes(
	phase: LifecycleFailurePhase,
	terminationReason: LifecycleTerminationReason,
) {
	const taxonomy = LIFECYCLE_FAILURE_TAXONOMY[phase];
	return {
		"mcp.failure.phase": phase,
		"mcp.termination.reason": terminationReason,
		"error.type": taxonomy.errorType,
		"error.category": taxonomy.errorCategory,
	};
}

export function recordLifecycleFailure(
	span: Span,
	error: Error | string,
	phase: LifecycleFailurePhase,
	terminationReason: LifecycleTerminationReason,
): void {
	const attributes = createLifecycleFailureAttributes(phase, terminationReason);
	span.addEvent("mcp.lifecycle.failure", attributes);
	const failure = {
		kind: "lifecycle",
		attributes,
		span,
	} satisfies FailureContext;
	captureFailure(
		error,
		isExpectedLifecycleFailure(error)
			? { ...failure, expected: true }
			: failure,
	);
}

export type NodeLifecycleTransport = "stdio" | "http";

export interface NodeLifecycleContext {
	readonly signal: AbortSignal;
	/** Mark the beginning of a stdio transport connection attempt. */
	markConnectAttempted(): void;
	/** Mark a successful stdio transport connection. */
	markConnectSucceeded(): void;
	/** Mark the HTTP listener as successfully started. */
	markListening(): void;
	/** Register a partially acquired target so startup failure can close it. */
	adoptTarget(target: NodeLifecycleTarget): NodeLifecycleTarget;
}

export interface NodeLifecycleTarget {
	close(): Promise<void>;
}

export type NodeLifecycleOutcome =
	| {
			transport: "stdio";
			connectAttempted: boolean;
			connectSucceeded: boolean;
	  }
	| {
			transport: "http";
			listening: boolean;
	  };

export interface NodeLifecycleStartupResult {
	target: NodeLifecycleTarget;
	onShutdown?: (succeeded: boolean) => void | Promise<void>;
}

export interface RunNodeLifecycleOptions {
	transport: NodeLifecycleTransport;
	readonly start: (
		context: NodeLifecycleContext,
	) => Promise<NodeLifecycleStartupResult>;
	readonly onFailure?: (
		reason: LifecycleTerminationReason,
		outcome: NodeLifecycleOutcome,
	) => void;
}

export interface NodeLifecycleHandle {
	close(): Promise<void>;
}

function createOutcomeState(transport: NodeLifecycleTransport) {
	let connectAttempted = false;
	let connectSucceeded = false;
	let listening = false;
	return {
		markConnectAttempted: () => {
			connectAttempted = true;
		},
		markConnectSucceeded: () => {
			connectSucceeded = true;
		},
		markListening: () => {
			listening = true;
		},
		getOutcome: (): NodeLifecycleOutcome =>
			transport === "stdio"
				? { transport, connectAttempted, connectSucceeded }
				: { transport, listening },
	};
}

function classifyFailure(
	outcome: NodeLifecycleOutcome,
): LifecycleTerminationReason {
	if (outcome.transport === "stdio") {
		if (outcome.connectAttempted && !outcome.connectSucceeded) {
			return "connect_failure";
		}
		return outcome.connectSucceeded ? "runtime_failure" : "startup_failure";
	}
	return outcome.listening ? "runtime_failure" : "startup_failure";
}

function asError(error: Error | string): Error {
	return error instanceof Error ? error : new Error(String(error));
}

/** Owns process-wide Node lifecycle concerns while leaving transport state local. */
export async function runNodeLifecycle({
	transport,
	start,
	onFailure,
}: RunNodeLifecycleOptions): Promise<NodeLifecycleHandle> {
	const processScope = await Effect.runPromise(Scope.make());
	if (telemetryLayer) {
		await Effect.runPromise(
			Layer.buildWithScope(telemetryLayer, processScope).pipe(
				Effect.catch(() => Effect.void),
			),
		);
	}
	const lifecycleController = new AbortController();
	const state = createOutcomeState(transport);
	let processScopeClosePromise: Promise<void> | undefined;
	const closeProcessScope = (): Promise<void> => {
		if (processScopeClosePromise) return processScopeClosePromise;
		processScopeClosePromise = Effect.runPromise(
			Scope.close(processScope, Exit.succeed(undefined)),
		)
			.catch(() => undefined)
			.then(async () => {
				// Keep compatibility with test doubles and alternate telemetry
				// implementations that do not provide a Layer.
				if (!telemetryLayer) await flushTelemetry().catch(() => undefined);
			});
		return processScopeClosePromise;
	};

	let resolveReady: (handle: NodeLifecycleHandle) => void = () => undefined;
	let rejectReady: (error?: Error | string | LifecycleFailure) => void = () =>
		undefined;
	const ready = new Promise<NodeLifecycleHandle>((resolve, reject) => {
		resolveReady = resolve;
		rejectReady = reject;
	});
	let resolveCompletion: () => void = () => undefined;
	const completion = new Promise<void>((resolve) => {
		resolveCompletion = resolve;
	});
	let completionReported = false;
	const startupCleanups = new Set<() => Promise<void>>();
	const adoptedTargets = new WeakMap<
		NodeLifecycleTarget,
		NodeLifecycleTarget
	>();
	const adoptTarget = (target: NodeLifecycleTarget): NodeLifecycleTarget => {
		const existing = adoptedTargets.get(target);
		if (existing) return existing;
		let closePromise: Promise<void> | undefined;
		const close = (): Promise<void> => {
			if (closePromise) return closePromise;
			closePromise = Promise.resolve()
				.then(() => target.close())
				.catch((error) => {
					throw error;
				});
			return closePromise;
		};
		startupCleanups.add(close);
		const adopted = { close };
		adoptedTargets.set(target, adopted);
		return adopted;
	};
	const context: NodeLifecycleContext = {
		signal: lifecycleController.signal,
		markConnectAttempted: () => state.markConnectAttempted(),
		markConnectSucceeded: () => state.markConnectSucceeded(),
		markListening: () => state.markListening(),
		adoptTarget,
	};

	serverStartups.add(1, { version: serviceVersion });
	let span: Span | undefined;
	const ownerProgram = Effect.gen(function* () {
		yield* Effect.acquireRelease(
			Effect.try({
				try: installProcessExceptionTracking,
				catch: (cause) =>
					new LifecycleFailure({
						cause: cause instanceof Error ? cause : String(cause),
						phase: "run",
					}),
			}),
			(cleanup) => Effect.sync(cleanup),
		);
		yield* Effect.acquireRelease(Effect.succeed(undefined), () =>
			Effect.promise(async () => {
				for (const cleanup of Array.from(startupCleanups).toReversed()) {
					await cleanup().catch(() => undefined);
				}
			}),
		);

		const result = yield* Effect.tryPromise({
			try: () => start(context),
			catch: (cause) =>
				new LifecycleFailure({
					cause: cause instanceof Error ? cause : String(cause),
					phase: "run",
				}),
		});
		const target = result.target;
		const ownedTarget = adoptTarget(target);
		const cancelUpdateCheck = yield* Effect.try({
			try: () =>
				scheduleUpdateCheck({
					packageName: serviceName,
					currentVersion: serviceVersion,
				}),
			catch: (cause) =>
				new LifecycleFailure({
					cause: cause instanceof Error ? cause : String(cause),
					phase: "run",
				}),
		});
		yield* Effect.acquireRelease(Effect.succeed(cancelUpdateCheck), (cancel) =>
			Effect.sync(() => cancel?.()),
		);

		const shutdown = yield* Effect.try({
			try: () =>
				installGracefulShutdown({
					target,
					closeTarget: () => ownedTarget.close(),
					cancel: lifecycleController,
					onComplete: async (succeeded) => {
						if (completionReported) return;
						completionReported = true;
						try {
							await result.onShutdown?.(succeeded);
						} finally {
							resolveCompletion();
							await closeProcessScope();
						}
					},
				}),
			catch: (cause) =>
				new LifecycleFailure({
					cause: cause instanceof Error ? cause : String(cause),
					phase: "run",
				}),
		});
		if (shutdown) {
			yield* Effect.acquireRelease(Effect.succeed(shutdown), (controller) =>
				Effect.sync(() => controller.cleanup()),
			);
		}

		resolveReady({
			close: shutdown ? () => shutdown.close() : () => target.close(),
		});
		span?.setStatus({ code: SpanStatusCode.OK });
		if (!shutdown) resolveCompletion();
		yield* Effect.promise(() => completion);
	});

	const ownerFiber = await Effect.runPromise(
		Effect.forkIn(
			ownerProgram.pipe(
				Effect.tapError((error) =>
					Effect.sync(() => {
						rejectReady(error);
					}),
				),
			),
			processScope,
			{ startImmediately: true },
		).pipe(Effect.provideService(Scope.Scope, processScope)),
	);
	const ownerCompletion = new Promise<void>((resolve) => {
		ownerFiber.addObserver(() => {
			void closeProcessScope().finally(resolve);
		});
	});

	await tracer.startActiveSpan(
		"mcp.server.run",
		{
			attributes: {
				"mcp.span.category": "startup",
				"mcp.transport": transport,
			},
		},
		async (startupSpan) => {
			span = startupSpan;
			try {
				await ready;
			} catch (error) {
				const outcome = state.getOutcome();
				const reason = classifyFailure(outcome);
				const projectedError =
					error instanceof LifecycleFailure
						? asError(error.cause)
						: asError(error instanceof Error ? error : String(error));
				if (!(outcome.transport === "stdio" && reason === "connect_failure")) {
					recordLifecycleFailure(startupSpan, projectedError, "run", reason);
				}
				onFailure?.(reason, outcome);
				startupSpan.setStatus({ code: SpanStatusCode.ERROR });
				await ownerCompletion;
				throw projectedError;
			} finally {
				startupSpan.end();
			}
		},
	);

	return await ready;
}

export type { LifecycleFailurePhase, LifecycleTerminationReason };

/**
 * Centralized telemetry initialization.
 *
 * It sets up independent telemetry paths: Sentry error events and an OTel
 * Collector (traces + metrics to Honeycomb).
 *
 * Sentry SDK: error monitoring, release tracking
 * OTel Collector → Honeycomb: performance traces, metrics
 */

import { randomBytes, randomUUID as nodeRandomUUID } from "node:crypto";
import { z } from "zod";
import { Effect, Layer } from "effect";
import * as Sentry from "@sentry/node";
import { metrics, trace } from "@opentelemetry/api";

import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import {
	AggregationTemporalityPreference,
	OTLPMetricExporter,
} from "@opentelemetry/exporter-metrics-otlp-http";
import { resourceFromAttributes } from "@opentelemetry/resources";
import {
	AlwaysOnSampler,
	BatchSpanProcessor,
	type SpanProcessor,
} from "@opentelemetry/sdk-trace-base";
import { NodeTracerProvider } from "@opentelemetry/sdk-trace-node";
import {
	MeterProvider,
	PeriodicExportingMetricReader,
} from "@opentelemetry/sdk-metrics";
import { captureFailure, sanitizeSentryEvent } from "./failure-reporter.js";
export type ProcessExceptionSource = {
	on(
		event: "uncaughtExceptionMonitor" | "unhandledRejection",
		listener: (error: Error | string) => void,
	): void;
	removeListener(
		event: "uncaughtExceptionMonitor" | "unhandledRejection",
		listener: (error: Error | string) => void,
	): void;
};

const PROCESS_FAILURE_TAXONOMY = {
	uncaughtException: "uncaught_exception",
	unhandledRejection: "unhandled_rejection",
} as const;

export function installProcessExceptionTracking(
	processLike: ProcessExceptionSource = process,
): () => void {
	if (!telemetryEnabled) return () => {};
	const recordProcessException = (
		source: keyof typeof PROCESS_FAILURE_TAXONOMY,
		error: Error | string,
	) => {
		try {
			tracer.startActiveSpan(
				`mcp.process.${source}`,
				{ attributes: { "mcp.span.category": "process" } },
				(span) => {
					try {
						captureFailure(error, {
							kind: "process",
							attributes: {
								"exception.source": source,
								"mcp.failure.phase": PROCESS_FAILURE_TAXONOMY[source],
								"error.type": "MCP_PROCESS_EXCEPTION",
								"error.category": "McpProcessFailure",
							},
							span,
						});
					} finally {
						span.end();
					}
				},
			);
		} catch {
			// Process telemetry must never affect Node's lifecycle.
		}
	};
	const uncaughtException = (error: Error | string) =>
		recordProcessException("uncaughtException", error);
	const unhandledRejection = (error: Error | string) =>
		recordProcessException("unhandledRejection", error);
	let cleaned = false;
	const installedListeners: Array<{
		event: "uncaughtExceptionMonitor" | "unhandledRejection";
		listener: (error: Error | string) => void;
	}> = [];
	const removeInstalledListeners = () => {
		if (cleaned) return;
		cleaned = true;
		for (const { event, listener } of installedListeners.toReversed()) {
			try {
				processLike.removeListener(event, listener);
			} catch {
				// Listener cleanup must not replace the original acquisition error.
			}
		}
	};

	try {
		const listeners = [
			["uncaughtExceptionMonitor", uncaughtException],
			["unhandledRejection", unhandledRejection],
		] as const;
		for (const [event, listener] of listeners) {
			processLike.on(event, listener);
			installedListeners.push({ event, listener });
		}
	} catch (error) {
		removeInstalledListeners();
		throw error;
	}

	return () => {
		removeInstalledListeners();
	};
}

function readBuildGlobal<T>(read: () => T): T | undefined {
	try {
		return read();
	} catch {
		return undefined;
	}
}

function parseBuildString<T>(value: T, fallback: string): string {
	return z.string().parse(value ?? fallback);
}
declare const __HEVY_MCP_NAME__: string | undefined;
declare const __HEVY_MCP_VERSION__: string | undefined;
declare const __HEVY_MCP_BUILD__: boolean | undefined;
declare const __OTEL_COLLECTOR_TOKEN__: string | undefined;

const name = parseBuildString(
	readBuildGlobal(() => __HEVY_MCP_NAME__),
	"hevy-mcp",
);
const version = parseBuildString(
	readBuildGlobal(() => __HEVY_MCP_VERSION__),
	"dev",
);

const telemetryEnabled = process.env.HEVY_MCP_TELEMETRY !== "0";

// Collector token is injected at build time from the OTEL_COLLECTOR_TOKEN
// GitHub secret via tsdown.config.ts define. The collector forwards
// traces and metrics to Honeycomb, keeping the Honeycomb API key off the
// client. The collector endpoint is public (behind Cloudflare Tunnel).
const collectorToken =
	z.string().safeParse(readBuildGlobal(() => __OTEL_COLLECTOR_TOKEN__)).data ??
	process.env.OTEL_COLLECTOR_TOKEN ??
	"";

const COLLECTOR_ENDPOINT = "https://otel.chrisdoc.dev/v1";
const DEFAULT_SENTRY_DSN =
	"https://ce696d8333b507acbf5203eb877bce0f@o4508975499575296.ingest.de.sentry.io/4509049671647312";
const sentryRelease = process.env.SENTRY_RELEASE ?? `${name}@${version}`;

/** Hex-encode bytes without relying on Buffer typings that vary across @types/node releases. */
function toHex(bytes: Uint8Array): string {
	let hex = "";
	for (const byte of bytes) hex += byte.toString(16).padStart(2, "0");
	return hex;
}

export function createServiceInstanceId(
	generate: () => string = nodeRandomUUID,
): string {
	try {
		const generated = generate();
		if (generated.length > 0 && generated.length <= 128) return generated;
	} catch {
		// Fall back to a process-local opaque identifier.
	}
	return toHex(randomBytes(16));
}

const serviceInstanceId = createServiceInstanceId();

const resource = resourceFromAttributes({
	"service.name": name,
	"service.version": version,
	"service.instance.id": serviceInstanceId,
	"process.runtime.name": process.release.name,
	"process.runtime.version": process.version,
});

let tracerProvider: NodeTracerProvider | undefined;
let meterProvider: MeterProvider | undefined;
let telemetryInitialized = false;

function initializeTelemetry(): void {
	if (telemetryInitialized || !telemetryEnabled) return;
	try {
		const rawDsn = process.env.SENTRY_DSN ?? DEFAULT_SENTRY_DSN;
		const isValidDsn =
			z.string().safeParse(rawDsn).success &&
			rawDsn.length > 0 &&
			!rawDsn.startsWith("*");

		// --- Sentry error monitoring ---
		Sentry.init({
			dsn: isValidDsn ? rawDsn : undefined,
			release: sentryRelease,
			tracesSampleRate: 0.0,
			sendClientReports: false,
			sendDefaultPii: false,
			beforeSend: sanitizeSentryEvent,
			integrations: (integrations) =>
				integrations.filter(
					(integration) =>
						integration.name !== "OnUncaughtException" &&
						integration.name !== "OnUnhandledRejection",
				),
			skipOpenTelemetrySetup: true,
			registerEsmLoaderHooks: false,
			ignoreErrors: ["EPIPE", "broken pipe"],
		});

		const spanProcessors: SpanProcessor[] = [];

		// OTel Collector → Honeycomb traces — only if token is available
		if (collectorToken) {
			spanProcessors.push(
				new BatchSpanProcessor(
					new OTLPTraceExporter({
						url: `${COLLECTOR_ENDPOINT}/traces`,
						headers: {
							Authorization: `Bearer ${collectorToken}`,
						},
					}),
				),
			);
		}

		tracerProvider = new NodeTracerProvider({
			resource,
			sampler: new AlwaysOnSampler(),
			spanProcessors,
		});

		tracerProvider.register();

		// --- OpenTelemetry meter provider (→ Collector → Honeycomb metrics) ---
		if (collectorToken) {
			meterProvider = new MeterProvider({
				resource,
				readers: [
					new PeriodicExportingMetricReader({
						exporter: new OTLPMetricExporter({
							url: `${COLLECTOR_ENDPOINT}/metrics`,
							headers: {
								Authorization: `Bearer ${collectorToken}`,
							},
							temporalityPreference: AggregationTemporalityPreference.DELTA,
						}),
						exportIntervalMillis: 30_000,
					}),
				],
			});
			metrics.setGlobalMeterProvider(meterProvider);
		}

		trace.setGlobalTracerProvider(tracerProvider);
		telemetryInitialized = true;
	} catch (error) {
		telemetryInitialized = false;
		tracerProvider = undefined;
		meterProvider = undefined;
		throw error;
	}
}

/**
 * Process-scoped telemetry. Importing this module only creates inert OTel
 * handles; provider registration and Sentry initialization happen when the
 * lifecycle acquires this layer.
 */
export const initializeTelemetryEffect = Effect.try({
	try: initializeTelemetry,
	catch: (error) => error,
});

export const telemetryLayer = Layer.effectDiscard(
	initializeTelemetryEffect.pipe(
		Effect.catch(() => Effect.void),
		Effect.andThen(
			Effect.addFinalizer(() =>
				Effect.promise(() => flushTelemetry().catch(() => undefined)),
			),
		),
	),
);

export async function flushTelemetry(timeoutMs = 1_000): Promise<void> {
	if (!telemetryEnabled) {
		return;
	}

	const flushPromise = Promise.allSettled([
		...(tracerProvider
			? [Promise.resolve().then(() => tracerProvider?.forceFlush())]
			: []),
		...(meterProvider
			? [Promise.resolve().then(() => meterProvider?.forceFlush())]
			: []),
		Promise.resolve().then(() => Sentry.flush(timeoutMs)),
	]);
	let timeout: ReturnType<typeof setTimeout> | undefined;
	const timeoutPromise = new Promise<void>((resolve) => {
		timeout = setTimeout(resolve, timeoutMs);
	});
	try {
		await Promise.race([flushPromise, timeoutPromise]);
	} finally {
		clearTimeout(timeout);
	}
}

